const body = $input.first().json.body || $input.first().json;
const eventType = body.eventType || '';
const data = body.data || {};
const store = $getWorkflowStaticData('global');
if (!store.shipments) store.shipments = {};

const NAMES = {
  'th-flash': 'Flash Express',
  'th-kerry': 'Kerry Express',
  'th-post': 'Thailand Post',
  'th-jt': 'J&T Express',
  'cm-sameday': 'Chiang Mai same-day',
};
const STEPS = ['placed', 'booked', 'pickup', 'transit', 'delivered'];

function noteFor(row) {
  if (row.current === 'booked') return row.courierName + ' is hired. The trail updates after they pick up the parcel.';
  if (row.current === 'pickup') return row.courierName + ' picked up the parcel.';
  if (row.current === 'transit') {
    return row.trackingNumber
      ? row.courierName + ' is carrying this order. Tracking number ' + row.trackingNumber + '.'
      : row.courierName + ' is carrying this order.';
  }
  if (row.current === 'delivered') return row.courierName + ' delivered this order.';
  return row.courierName + ' has this order.';
}

function present(row) {
  return {
    success: true,
    found: true,
    orderId: row.orderId,
    courierId: row.courierId,
    courierName: row.courierName,
    current: STEPS.includes(row.current) ? row.current : 'booked',
    trackingNumber: row.trackingNumber || '',
    updatedAt: row.updatedAt,
    statusNote: row.statusNote || noteFor(row),
  };
}

function remember(row) {
  const ids = Object.keys(store.shipments);
  if (ids.length > 200) {
    ids.sort((a, b) => String(store.shipments[a].updatedAt).localeCompare(String(store.shipments[b].updatedAt)));
    ids.slice(0, ids.length - 200).forEach((id) => { delete store.shipments[id]; });
  }
  store.shipments[row.orderId] = row;
}

if (eventType === 'order.courier_book') {
  const existing = store.shipments[data.orderId];
  if (existing && existing.trackingToken === data.trackingToken) {
    return [{ json: present(existing) }];
  }
  const courierName = NAMES[data.courierId] || data.courierName || 'Hired courier';
  const row = {
    orderId: data.orderId,
    trackingToken: data.trackingToken,
    courierId: data.courierId || '',
    courierName,
    regionState: data.regionState || '',
    country: data.country || 'Thailand',
    trackingNumber: '',
    current: 'booked',
    updatedAt: new Date().toISOString(),
    statusNote: '',
  };
  row.statusNote = noteFor(row);
  remember(row);
  return [{ json: present(row) }];
}

if (eventType === 'order.courier_event') {
  const row = store.shipments[data.orderId];
  if (!row || row.trackingToken !== data.trackingToken) {
    return [{ json: { success: true, found: false, message: 'Courier shipment not booked yet' } }];
  }
  if (STEPS.includes(data.current)) row.current = data.current;
  if (data.trackingNumber) row.trackingNumber = String(data.trackingNumber);
  row.updatedAt = new Date().toISOString();
  row.statusNote = data.statusNote || noteFor(row);
  remember(row);
  return [{ json: present(row) }];
}

if (eventType === 'order.courier_track') {
  const orders = Array.isArray(data.orders) ? data.orders : [{ orderId: data.orderId, trackingToken: data.trackingToken }];
  const results = {};
  orders.forEach((order) => {
    const row = store.shipments[order.orderId];
    if (!row || row.trackingToken !== order.trackingToken) {
      results[order.orderId] = { success: true, found: false, message: 'Courier shipment not booked yet' };
      return;
    }
    results[order.orderId] = present(row);
  });
  return [{ json: { success: true, batch: true, results } }];
}

return [{ json: { success: false, found: false, message: 'Unknown courier event' } }];
